// Confere a assinatura HMAC (horário + corpo bruto). Pedido velho ou adulterado vira valid=false,
// e o fluxo responde 401: o outbox da API nunca marca como entregue o que não foi processado.
const crypto = require('crypto');
const secret = $env.H2D_HMAC_SECRET;
if (!secret) return [{ json: { valid: false, reason: 'H2D_HMAC_SECRET não configurado' } }];
const headers = $input.first().json.headers || {};
const ts = headers['x-h2d-timestamp'];
const sig = String(headers['x-h2d-signature'] || '');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.`).update(raw).digest('hex');
const a = Buffer.from(sig);
const b = Buffer.from(expected);
const signatureOk = a.length === b.length && crypto.timingSafeEqual(a, b);
const age = Math.abs(Date.now() / 1000 - Number(ts));
if (!ts || !signatureOk || !(age <= 300)) return [{ json: { valid: false, reason: 'Assinatura inválida' } }];
const event = JSON.parse(raw.toString('utf8'));
const store = $getWorkflowStaticData('global');
const seen = store.seen || [];
return [{ json: { valid: true, duplicate: seen.includes(event.event_id), event } }];

// Decide para quem e o que enviar, conforme o tipo do evento.
const e = $json.event;
const p = e.payload || {};
const leader = $env.TI_LEADER_EMAIL || '';
const base = ($env.H2D_BASE_URL || '').replace(/\/$/, '');
const link = base ? `\n\nAbrir no sistema: ${base}/chamados` : '';
let to = '';
let cc = '';
let subject = '';
let text = '';
if (e.type === 'ticket.created') {
  to = (p.assignee && p.assignee.email) || leader;
  if (p.notify_leader && leader && leader !== to) cc = leader;
  subject = `[H2D] Novo chamado ${p.code}${p.priority ? ' (' + p.priority + ')' : ''}: ${p.summary}`;
  text = `Novo chamado ${p.code}\nPrioridade: ${p.priority || 'não definida'}\nSolicitante: ${p.requester && p.requester.name}\nResponsável: ${p.assignee ? p.assignee.name : 'ninguém ainda (triagem manual)'}\nPrazo de resolução: ${p.resolution_due || 'não definido'}\n\n${p.summary}${link}`;
} else if (e.type === 'ticket.assigned') {
  to = (p.assignee && p.assignee.email) || '';
  subject = `[H2D] Chamado ${p.code} atribuído a você`;
  text = `O chamado ${p.code} foi atribuído a você.\nPrioridade: ${p.priority || 'não definida'}\nSolicitante: ${p.requester && p.requester.name}\n\n${p.summary}${link}`;
} else if (e.type === 'ticket.resolved') {
  to = (p.requester && p.requester.email) || '';
  subject = `[H2D] Seu chamado ${p.code} foi resolvido`;
  text = `Olá! O chamado ${p.code} (${p.summary}) foi resolvido pela equipe de TI.\nSe o problema voltar, responda no próprio chamado.`;
} else if (e.type === 'ticket.sla_alert') {
  const estouro = p.level === 100;
  to = (p.assignee && p.assignee.email) || leader;
  if (estouro && leader && leader !== to) cc = leader;
  subject = estouro ? `[H2D] SLA ESTOURADO: ${p.code} (${p.summary})` : `[H2D] SLA em risco (75% do prazo): ${p.code}`;
  text = `${estouro ? 'O prazo de resolução ESTOUROU' : 'O prazo de resolução passou de 75%'} no chamado ${p.code}.
Prioridade: ${p.priority || 'não definida'}
Responsável: ${p.assignee ? p.assignee.name : 'ninguém ainda'}
Prazo: ${p.resolution_due || 'não definido'}

${p.summary}${link}`;
}
return [{ json: { event_id: e.event_id, type: e.type, send: Boolean(to), to, cc, subject, text } }];

// Só depois do envio o evento vira "processado": se o e-mail falhar, a nova tentativa do outbox passa.
const id = $('Montar aviso').first().json.event_id;
const store = $getWorkflowStaticData('global');
const seen = store.seen || [];
if (!seen.includes(id)) seen.push(id);
store.seen = seen.slice(-500);
return [{ json: { ok: true, event_id: id } }];
